 "content": "from collections import deque


def transform(grid):
    """Recover large, nearly rectangular colored panels from a noisy canvas."""
    h, w = len(grid), len(grid[0])
    # The canvas color is the most frequent color; non-background isolated
    # speckles are noise, while panels form dense connected components.
    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    background = max(range(10), key=lambda color: counts[color])
    seen = [[False] * w for _ in range(h)]
    panels = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            r0 = min(rr for rr, _ in cells)
            r1 = max(rr for rr, _ in cells)
            c0 = min(cc for _, cc in cells)
            c1 = max(cc for _, cc in cells)
            area = (r1-r0+1) * (c1-c0+1)
            # Large dense components identify panels; their missing cells are
            # overprinted by noise and should be restored to the panel color.
            if area >= 10 and len(cells) / area >= 0.50:
                panels.append((r0, r1, c0, c1, color))
    out = [[background for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in panels:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
